mapper.insert:
INSERT INTO woorido.posts (
    id, challenge_id, created_by, content, is_notice, is_pinned,
    like_count, comment_count, view_count, created_at, updated_at
) VALUES (
    #{id}, #{challengeId}, #{createdBy}, #{content}, #{isNotice}, #{isPinned},
    #{likeCount}, #{commentCount}, #{viewCount}, #{createdAt}, #{updatedAt, jdbcType=TIMESTAMP}
)

mapper.update:
UPDATE woorido.posts
SET content = #{content},
    is_notice = #{isNotice},
    is_pinned = #{isPinned},
    updated_at = #{updatedAt, jdbcType=TIMESTAMP}
WHERE id = #{id}

UPDATE woorido.posts
SET view_count = view_count + 1
WHERE id = #{id}

UPDATE woorido.posts
SET like_count = like_count + 1
WHERE id = #{id}

UPDATE woorido.posts
SET like_count = CASE WHEN like_count > 0 THEN like_count - 1 ELSE 0 END
WHERE id = #{id}

UPDATE woorido.posts
SET deleted_at = CURRENT_TIMESTAMP
WHERE id = #{id}

mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM woorido.post_likes
WHERE post_id = #{postId} AND user_id = #{userId}

SELECT * FROM ( SELECT A.*, ROWNUM RNUM FROM ( SELECT p.id as ID, p.challenge_id as CHALLENGE_ID, p.created_by as CREATED_BY, p.content as CONTENT, p.is_notice as IS_NOTICE, p.is_pinned as IS_PINNED, p.like_count as LIKE_COUNT, p.comment_count as COMMENT_COUNT, p.view_count as VIEW_COUNT, p.created_at as CREATED_AT, u.nickname as AUTHOR_NICKNAME, u.profile_image_url as AUTHOR_PROFILE_IMAGE FROM woorido.posts p JOIN woorido.users u ON p.created_by = u.id WHERE p.challenge_id = #{challengeId} AND p.deleted_at IS NULL
AND p.is_notice = #{isNotice}
ORDER BY p.is_pinned DESC, ${sortColumn} ${sortOrder} ) A WHERE ROWNUM <= #{endRow} ) WHERE RNUM > #{startRow}
